	private long genericCount(String query) {
		return count(query, false);
	}

	private long nativeCount(String query) {
		return count(query, true);
	}

	private long count(String query, boolean nativeEnabled) {
		return ((org.eclipse.rdf4j.model.Literal) rows(query, nativeEnabled).get(0).getValue("c")).longValue();
	}

	private List<String> genericRows(String query) {
		return rows(query, false).stream().map(LmdbNativeKernelRangeTest::render).sorted().toList();
	}

	private List<String> nativeRows(String query) {
		return rows(query, true).stream().map(LmdbNativeKernelRangeTest::render).sorted().toList();
	}

	private List<BindingSet> rows(String query, boolean nativeEnabled) {
		System.setProperty("rdf4j.lmdb.nativeQueryEngine.enabled", Boolean.toString(nativeEnabled));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			return QueryResults.asList(connection.prepareTupleQuery(query).evaluate());
		}
	}

	private static String render(BindingSet bindings) {
		List<String> values = new ArrayList<>(bindings.size());
		for (String name : List.of("s", "score", "g", "c")) {
			if (bindings.hasBinding(name)) {
				values.add(bindings.getValue(name).stringValue());
			}
		}
		return String.join("=", values);
	}

	private static String prefixes() {
		return "PREFIX ex: <" + EX + ">\n";
	}
